          texto:
            "De ahí salen la España de pandereta, el bandolero, la gitana y el fraile, y de ahí sale también el turismo. La leyenda negra bélica del dieciséis y la leyenda pintoresca del diecinueve son cosas distintas, y el libro las mezcla más de lo debido.",
